solution:
%dw 2.0
output application/json
var layout = [
  { name: "id", start: 0, length: 6 },
  { name: "name", start: 6, length: 20 },
  { name: "salary", start: 26, length: 10 },
  { name: "dept", start: 36, length: 3 }
]
fun field(line, start, length) = trim(line[start to (start + length - 1)])
fun parseLine(line) = layout reduce (f, acc = {}) -> acc ++ { (f.name): field(line, f.start, f.length) }
---
(payload splitBy "\n") filter !isEmpty(trim($)) map (line) -> do {
  var rec = parseLine(line)
  ---
  { id: rec.id, name: rec.name, salary: rec.salary as Number, dept: rec.dept }
}
